<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import DataChart from '@/components/DataChart.vue'
import {cancelExperiment,createExperiment,getAudit,getExperiment,getExperiments,getSafnetInfo,getSampleStatistics} from '@/api/ml'
import type {Audit,Experiment,SampleStatistics} from '@/types/ml'
const audit=ref<Audit>(),stats=ref<SampleStatistics>(),experiments=ref<Experiment[]>([]),active=ref<Experiment>(),safnet=ref<any>(),loading=ref(false),error=ref('')
const form=reactive({name:'',model_type:'lstm',quality_profile:'strict',epochs:30,batch_size:128,learning_rate:.003,hidden_size:16,num_layers:1,dropout:0,patience:6,seed:42,cnn_channels:[32,64],time_embedding:96,attention_heads:8,attention_layers:1,fusion_hidden:128})
let timer:number|undefined
const isSafnet=computed(()=>form.model_type==='safnet'),safnetReady=computed(()=>!!safnet.value?.availability?.ready)
const curveOption=computed(()=>({tooltip:{trigger:'axis'},legend:{data:['训练损失','验证损失']},xAxis:{type:'category',data:active.value?.training_curve.map(r=>r.epoch)??[]},yAxis:{type:'value',name:'标准化 MSE'},series:[{name:'训练损失',type:'line',showSymbol:false,data:active.value?.training_curve.map(r=>r.train_loss)??[]},{name:'验证损失',type:'line',showSymbol:false,data:active.value?.training_curve.map(r=>r.validation_loss)??[]}]}))
async function refresh(){experiments.value=await getExperiments();const running=experiments.value.find(r=>['queued','preparing','training','evaluating'].includes(r.status));if(running)active.value=await getExperiment(running.id)}
async function load(){loading.value=true;error.value='';try{[audit.value,stats.value,safnet.value]=await Promise.all([getAudit(),getSampleStatistics(form.quality_profile),getSafnetInfo()]);await refresh()}catch{error.value='训练数据或模型信息加载失败，请确认后端状态。'}finally{loading.value=false}}
async function updateStats(){stats.value=await getSampleStatistics(form.quality_profile)}
async function start(){loading.value=true;try{const config=isSafnet.value?{epochs:form.epochs,batch_size:form.batch_size,learning_rate:form.learning_rate,patience:form.patience,seed:form.seed,cnn_channels:form.cnn_channels,time_embedding:form.time_embedding,attention_heads:form.attention_heads,attention_layers:form.attention_layers,fusion_hidden:form.fusion_hidden,dropout:form.dropout,time_features:1}:{epochs:form.epochs,batch_size:form.batch_size,learning_rate:form.learning_rate,hidden_size:form.hidden_size,num_layers:form.num_layers,dropout:form.dropout,patience:form.patience,seed:form.seed};active.value=await createExperiment({name:form.name||undefined,model_type:form.model_type,quality_profile:form.quality_profile,config});ElMessage.success('真实训练任务已创建')}catch(e:any){ElMessage.error(e.response?.data?.message||'训练任务创建失败')}finally{loading.value=false}}
async function cancel(){if(active.value)active.value=await cancelExperiment(active.value.id)}
onMounted(()=>{load();timer=window.setInterval(async()=>{if(active.value&&['queued','preparing','training','evaluating'].includes(active.value.status)){active.value=await getExperiment(active.value.id);if(!['queued','preparing','training','evaluating'].includes(active.value.status))await refresh()}},1000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><section v-loading="loading" class="page-stack"><div class="page-heading"><div><h2>模型训练</h2><p>历史时序基线与 SAF-Net 时空注意力融合网络</p></div></div><el-alert title="研究边界" description="测试集不参与训练、早停或参数选择；没有真实 ERA5 样本时不会生成模拟实验。" type="warning" :closable="false" show-icon/><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<el-card shadow="never" class="data-card"><template #header><strong>训练数据审计</strong></template><div v-if="audit" class="metric-grid"><div><span>有效 CMA 风速</span><strong>{{audit.valid_cma_wind_count.toLocaleString()}}</strong></div><div><span>缺失比例</span><strong>{{(audit.missing_cma_wind_ratio*100).toFixed(1)}}%</strong></div><div><span>严格样本</span><strong>{{audit.strict_sample_count.toLocaleString()}}</strong></div><div><span>扩展样本</span><strong>{{audit.extended_sample_count.toLocaleString()}}</strong></div><div><span>ERA5 时空样本</span><strong>{{safnet?.availability?.total??0}}</strong></div><div><span>SAF-Net 参数</span><strong>{{safnet?.parameters?.total?.toLocaleString()??'—'}}</strong></div></div></el-card>
<el-card shadow="never" class="data-card"><template #header><strong>新建训练实验</strong></template><el-form label-position="top" class="training-form"><el-form-item label="实验名称"><el-input v-model="form.name" placeholder="留空自动命名"/></el-form-item><el-form-item label="模型"><el-select v-model="form.model_type"><el-option label="Persistence" value="persistence"/><el-option label="Ridge" value="ridge"/><el-option label="LSTM" value="lstm"/><el-option label="GRU" value="gru"/><el-option label="SAF-Net" value="safnet"/></el-select></el-form-item><el-form-item label="质量配置"><el-select v-model="form.quality_profile" :disabled="isSafnet" @change="updateStats"><el-option label="严格 O/V（主实验）" value="strict"/><el-option label="扩展 O/V/I/P" value="extended"/></el-select></el-form-item>
<template v-if="['lstm','gru','safnet'].includes(form.model_type)"><el-form-item label="最大 Epoch"><el-input-number v-model="form.epochs" :min="1" :max="300"/></el-form-item><el-form-item label="Batch Size"><el-input-number v-model="form.batch_size" :min="1" :max="512"/></el-form-item><el-form-item label="学习率"><el-input-number v-model="form.learning_rate" :min=".0001" :max=".1" :step=".0005" :precision="4"/></el-form-item><el-form-item label="Early Stopping"><el-input-number v-model="form.patience" :min="1" :max="50"/></el-form-item><el-form-item label="Dropout"><el-input-number v-model="form.dropout" :min="0" :max=".8" :step=".1"/></el-form-item><el-form-item label="随机种子"><el-input-number v-model="form.seed"/></el-form-item></template>
<template v-if="isSafnet"><el-form-item label="CNN 通道 1"><el-input-number v-model="form.cnn_channels[0]" :min="4" :max="128"/></el-form-item><el-form-item label="CNN 通道 2"><el-input-number v-model="form.cnn_channels[1]" :min="4" :max="256"/></el-form-item><el-form-item label="时间嵌入维度"><el-input-number v-model="form.time_embedding" :min="8" :max="256"/></el-form-item><el-form-item label="注意力头数"><el-input-number v-model="form.attention_heads" :min="1" :max="16"/></el-form-item><el-form-item label="注意力层数"><el-input-number v-model="form.attention_layers" :min="1" :max="4"/></el-form-item><el-form-item label="融合隐藏维度"><el-input-number v-model="form.fusion_hidden" :min="16" :max="512"/></el-form-item></template></el-form>
<div v-if="stats&&!isSafnet" class="split-strip"><span>训练 {{(stats.splits.train as any).sample_count}} / {{(stats.splits.train as any).event_count}} 个事件</span><span>验证 {{(stats.splits.validation as any).sample_count}} / {{(stats.splits.validation as any).event_count}} 个事件</span><span>测试 {{(stats.splits.test as any).sample_count}} / {{(stats.splits.test as any).event_count}} 个事件</span><span>SID 交叉：{{(stats.splits.no_sid_leakage as boolean)?'无':'有'}}</span></div><el-alert v-if="isSafnet&&!safnetReady" title="当前尚无可用的 ERA5 时空样本，SAF-Net 训练暂不可用。" type="info" :closable="false"/><div v-if="isSafnet&&safnet" class="split-strip"><span>训练 {{safnet.availability.splits.train}} / {{safnet.availability.events?.train}} 个事件</span><span>验证 {{safnet.availability.splits.validation}} / {{safnet.availability.events?.validation}} 个事件</span><span>测试 {{safnet.availability.splits.test}} / {{safnet.availability.events?.test}} 个事件</span><span>设备 {{safnet.device}}</span><span>{{safnet.availability.formal_ready?'正式实验就绪':'小样本试验'}}</span></div><el-alert v-if="isSafnet&&safnet&&!safnet.availability.formal_ready" :title="safnet.availability.limitations.join('；')" type="warning" :closable="false"/><el-button type="primary" :disabled="(isSafnet&&!safnetReady)||(!!active&&['queued','preparing','training','evaluating'].includes(active.status))" @click="start">开始真实训练</el-button></el-card>
<el-card v-if="isSafnet&&safnet" shadow="never" class="data-card"><template #header><strong>SAF-Net 实际结构</strong></template><div class="architecture"><template v-for="(node,index) in safnet.pipeline" :key="node.name"><div><strong>{{node.name}}</strong><span>{{node.shape}}</span></div><b v-if="index<safnet.pipeline.length-1">→</b></template></div><div class="model-facts"><span>空间输入 B×4×2×31×31</span><span>时间输入 B×4×{{safnet.config.time_features}}</span><span>输出 B×1</span><span>可训练参数 {{safnet.parameters.trainable.toLocaleString()}}</span></div><p class="muted-note">空间注意力保留 31×31 位置权重；时间注意力为 4×4 多头矩阵。注意力只表示网络内部关注模式，不证明气象因果关系。当前无真实权重时不展示随机注意力。</p></el-card>
<el-card v-if="active" shadow="never" class="data-card"><template #header><div class="card-header"><strong>{{active.name}}</strong><el-tag>{{active.status}}</el-tag></div></template><el-progress :percentage="Math.round(active.progress)"/><p>阶段：{{active.phase}} · Epoch {{active.current_epoch}} / {{active.max_epochs||'无需迭代'}} · 设备 {{active.device||'准备中'}}</p><el-alert v-if="active.error_message" :title="active.error_message" type="error" :closable="false"/><el-button v-if="['queued','preparing','training','evaluating'].includes(active.status)" type="danger" plain @click="cancel">终止训练</el-button><DataChart v-if="active.training_curve.length&&active.model_type!=='ridge'" :option="curveOption" label="真实训练和验证损失曲线"/></el-card></section></template>
<style scoped>.page-stack>.el-alert:first-of-type{display:none}.architecture{display:flex;align-items:stretch;gap:10px;overflow:auto}.architecture>div{min-width:160px;padding:14px;background:#f3f7fa;border:1px solid #dbe5eb;border-radius:5px;display:flex;flex-direction:column;gap:8px}.architecture span,.model-facts{color:#617487;font-size:12px}.architecture b{align-self:center;color:#7890a2}.model-facts{display:flex;gap:18px;flex-wrap:wrap;margin:16px 0}</style>
